EXC={'.os-wrap.os-section-pad','.os-tcard.is-score','.os-wrap.os-section-pad.os-no-top','.page-wrapper.is-os','.main-wrapper.is-os','.os-h0.os-on-dark'}
def filt(css):
    out=[]
    for m in re.finditer(r'(@media[^{]+\{)?([^{}@]+)\{([^{}]*)\}\}?',css):
        sel=m.group(2).strip()
        if sel in EXC: continue
        if re.fullmatch(r'\.[\w-]+',sel) and sel[1:] in EX: continue
        out.append(m.group(0))
    return '\n'.join(out)
if __name__=='__main__': print(filt(open(sys.argv[1]).read()))
